mapper.insert:
INSERT INTO survey (
    title           
    , content       
    , start_date    
    , end_date      
    , use_yn        
    , reg_user      
    , reg_date      
) VALUES (
    #{title}
    , #{content}
    , #{startDate}
    , #{endDate}
    , #{useYn}
    , #{regUser}
    , NOW()
)

mapper.update:
UPDATE survey
SET
    title      = #{title}           
    , content    = #{content}       
    , start_date = #{startDate}     
    , end_date   = #{endDate}       
    , use_yn     = #{useYn}         
    , mod_user   = #{regUser}       
    , mod_date   = NOW()            
WHERE survey_no = #{surveyNo}

