INSERT INTO file_master (
    board_no    
    , file_path 
    , file_name 
    , org_name  
    , file_ext  
    , file_size 
    , sort_ord  
    , use_yn    
    , reg_user  
    , reg_date  
) VALUES (
    0
    , #{filePath}
    , #{fileName}
    , #{orgName}
    , #{fileExt}
    , #{fileSize}
    , 0
    , 'N'
    , #{regUser}
    , NOW()
)

mapper.update:
UPDATE file_master
SET    use_yn   = 'Y'           
     , board_no = #{boardNo}    
WHERE  file_no  = #{fileNo}

UPDATE file_master
SET    use_yn = 'N'         
WHERE  file_no = #{fileNo}

mapper.select:
SELECT s.survey_no AS surveyNo , s.title AS title , s.content AS content , DATE_FORMAT(s.start_date, '%Y-%m-%d') AS startDate , DATE_FORMAT(s.end_date, '%Y-%m-%d') AS endDate , CASE WHEN s.use_yn = 'Y' AND DATE(NOW()) BETWEEN DATE(s.start_date) AND DATE(s.end_date) THEN 'Y' ELSE 'N' END AS availYn , CASE WHEN r.res_no IS NOT NULL THEN 'Y' ELSE 'N' END AS responded FROM survey s LEFT JOIN response r ON r.survey_no = s.survey_no AND r.reg_user = #{userNo} WHERE s.use_yn = 'Y'
AND s.title LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY s.survey_no DESC LIMIT #{firstIndex}, #{recordCountPerPage}

mapper.insert:
INSERT INTO response (
    survey_no       
    , reg_user      
    , reg_date      
) VALUES (
    #{surveyNo}
    , #{regUser}
    , NOW()
)

INSERT INTO response_detail (
    res_no              
    , q_no              
    , answer_content    
    , option_no         
) VALUES (
    #{resNo}
    , #{qNo}
    , #{answerContent}
    , #{optionNo}
)

mapper.select:
SELECT COUNT(*)
FROM
    response
WHERE survey_no = #{surveyNo}
  AND reg_user  = #{userNo}
